import { Effect } from "effect";

type EffectOperation<TArgs extends readonly unknown[], TResult> = {
	readonly effect: (...args: TArgs) => Effect.Effect<TResult, unknown, never>;
};

export function requireOperation<T>(operation: T | undefined, id: string): T {
	if (operation === undefined) {
		throw new Error(`Operation ${id} is unavailable.`);
	}
	return operation;
}

export function operationEffect<TArgs extends readonly unknown[], TResult>(
	operation: EffectOperation<TArgs, TResult>,
	...args: TArgs
): Effect.Effect<TResult, unknown, never> {
	return Effect.suspend(() => operation.effect(...args));
}

import { preloadCompactJsonSchema } from "../utils/compact-json-schema.js";
import {
	getRegisteredToolConfig,
	registerToolDefinition,
	type ToolRegistrar,
} from "./define-tool.js";
import { bodyMeasurementToolDefinitions } from "./body-measurements.js";
import { folderToolDefinitions } from "./folders.js";
import { routineToolDefinitions } from "./routines.js";
import { templateToolDefinitions } from "./templates.js";
import { routineDiscoveryToolDefinitions } from "./routine-discovery.js";
import { workflowToolDefinitions } from "./workflows.js";
import { workoutToolDefinitions } from "./workouts.js";
