				created: true,
				commit_state: "confirmed",
				routine: null,
				routine_id: null,
				uses_rep_ranges: true,
			},
		});
	});

	it("returns the authoritative routine and ID when creation has a body", async () => {
		const client = createMockHevyClient();
		client.createRoutine.mockResolvedValue({
