		);
		expect(response.content[0]?.text).not.toContain("secret-token");
	});

	it("rejects legacy camelCase envelopes before invoking the client", () => {
		register(null);
		const definition = routineToolDefinitions.find(
			({ name }) => name === "create-routine",
