    43				if (
    44					normalizedQuery &&
    45					!routine.title?.toLocaleLowerCase().includes(normalizedQuery)
    46				) {
    47					continue;
    48				}
    49				routines.push(routine);
    50				if (routines.length >= limit) break;
    51			}
